import{_ as e,o as r,c as d,ag as a}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"Hermes Desktop 体验","description":"AI Agent 零基础教程","frontmatter":{"title":"Hermes Desktop 体验","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/05-hermes.md","filePath":"guide/05-hermes.md","lastUpdated":null}'),l={name:"guide/05-hermes.md"};function i(o,t,h,n,s,u){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="hermes-desktop-体验" tabindex="-1">Hermes Desktop 体验 <a class="header-anchor" href="#hermes-desktop-体验" aria-label="Permalink to &quot;Hermes Desktop 体验&quot;">​</a></h1><blockquote><p>状态：正文完成；共同基准任务已实测（2026-08-12）</p><p>本机版本：桌面应用 0.17.0（可执行文件版本 40.10.2 是 Electron 版本，不是产品版本）</p><p>最后本机核对：2026-08-12；订阅核验：2026-08-11</p></blockquote><h2 id="_1-一句话结论" tabindex="-1">1. 一句话结论 <a class="header-anchor" href="#_1-一句话结论" aria-label="Permalink to &quot;1. 一句话结论&quot;">​</a></h2><p><strong>高自主、模型自由、自托管型 Agent 的代表</strong>：预览/源码/差异/编辑四视图最灵活，也是本轮唯一触发并<strong>自动恢复真实路径错误</strong>的样本（误写 → 自动迁移 → 删除误建目录 → 哈希复核，全程无需人工）。「极客属性」来自模型接入、配置自由度与维护责任，而非界面简陋——GUI 本身成熟易用。适合有系统配置经验的读者，不适合零基础。</p><h2 id="_2-测试版本和地区" tabindex="-1">2. 测试版本和地区 <a class="header-anchor" href="#_2-测试版本和地区" aria-label="Permalink to &quot;2. 测试版本和地区&quot;">​</a></h2><ul><li>测试日期：2026-08-12（统一基准实测）；界面截图核验 2026-08-13</li><li>正式产品名称与测试入口：Hermes Desktop（Nous Research 的 Hermes Agent；注意与同名模型、纯 CLI 版本区分）</li><li>地区版本：国际开源项目（桌面应用 MIT License）</li><li>具体产品线：Desktop（三栏项目工作台）</li><li>账号区域与计费币种：无强制账号；模型账单来自所连接供应商</li><li>当前账号状态：无账号概念（应用本身开源）；本轮使用已配置的 Provider</li><li>官方服务是否覆盖当前地区：不适用（本地应用 + 外部 Provider）</li><li>注册、登录与支付前提：不需要产品注册；需要 Provider/API 配置</li><li>账号受限后的申诉与恢复入口：不适用；Provider 账单问题找对应供应商</li><li>桌面客户端版本：0.17.0</li><li>操作系统：Windows 10/11（官方支持 macOS 12+）</li><li>官方下载来源：官方发布页 / GitHub 仓库（NousResearch/hermes-agent）</li><li>入门分组：开源自主型 Agent</li><li>主要任务方向：高自主任务 / 自定义模型 / 自动化 / 长期项目</li><li>开放与后台运行方式：自托管（本地应用 + 外部模型供应商）</li><li>自主程度：高</li><li>建议基础：编程或系统配置经验</li><li>使用方案：开源免费（应用）；模型按供应商计费</li><li>官方订阅名称、价格与周期：应用 MIT 开源免费；Nous Portal 提供 Free、Plus、Super、Ultra 与月度 Credits（官方首页未展示可可靠引用的具体价格，正文写「以登录后 Portal 当前页面为准」）</li><li>套餐内用量单位：月度 Credits（Portal）；或第三方 API Token 账单</li><li>用量重置时间与结转规则：以 Portal 当前页面为准</li><li>官方 API 是否另行计费：可使用 Nous Portal、OpenRouter、OpenAI、自有端点及其他供应商</li><li>是否支持 BYOK：<strong>核心特性</strong>——多供应商自由接入</li><li>免费额度及核验来源：官方公开页未展示可直接引用的具体赠送额度</li><li>新用户或学生福利：无公开可引用信息</li><li>最后核验日期：2026-08-11</li><li>测试者背景：作者</li></ul><h2 id="_3-下载、安装与首次启动" tabindex="-1">3. 下载、安装与首次启动 <a class="header-anchor" href="#_3-下载、安装与首次启动" aria-label="Permalink to &quot;3. 下载、安装与首次启动&quot;">​</a></h2><ul><li>下载和安装：官方发布页下载 Windows 安装包，安装顺利（本机安装于 <code>%LOCALAPPDATA%\\hermes\\hermes-agent</code>）；</li><li>是否必须注册、登录或绑定其他服务：应用不需要；<strong>首次使用需配置 Provider（API Key/Endpoint）与模型</strong>——这是新手的主要门槛；</li><li>首次权限提示：可配置权限/审批模式；本轮为「智能审批」，未触发人工确认弹窗；</li><li>主界面导航：成熟三栏工作台——左侧新建会话、技能与工具、消息平台、产物、项目和 Profiles；中间会话、分支、上下文、模型选择；右侧项目文件树和终端；顶部布局编辑器、HUD 模式和侧栏控制；</li><li>新手从启动到完成第一个任务：新建 Project → 选择运行目录 → 配置 Provider 与模型 → 粘贴提示词 → 发送（需先跨过 Provider 配置）；</li><li>是否有只能通过 CLI/TUI 才能完成的重要能力：官方另有 CLI/Agent 形态；本页只评价 Desktop，未发现桌面端缺失本轮必需能力。</li></ul><h2 id="_4-免费额度、订阅与计费" tabindex="-1">4. 免费额度、订阅与计费 <a class="header-anchor" href="#_4-免费额度、订阅与计费" aria-label="Permalink to &quot;4. 免费额度、订阅与计费&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>实际记录</th><th>官方来源</th><th>最后核验日期</th></tr></thead><tbody><tr><td>免费额度</td><td>官方公开页未展示可引用的具体赠送额度</td><td>Hermes Agent 官网</td><td>2026-08-11</td></tr><tr><td>官方订阅</td><td>应用 MIT 开源免费；Nous Portal Free/Plus/Super/Ultra 含月度 Credits（价格以登录后页面为准）</td><td>Hermes Agent 官网</td><td>2026-08-11</td></tr><tr><td>用量单位与重置规则</td><td>Portal 月度 Credits；或第三方 API Token</td><td>官网</td><td>2026-08-11</td></tr><tr><td>新用户或学生福利</td><td>无公开可引用信息</td><td>—</td><td>2026-08-11</td></tr><tr><td>API 或 BYOK</td><td>支持 Nous Portal、OpenRouter、OpenAI、自有端点及其他供应商</td><td>官网 / GitHub</td><td>2026-08-11</td></tr></tbody></table><p><strong>实测补充</strong>：本轮使用 OpenCode Go + DeepSeek V4 Flash + 最高推理 + 智能审批；<strong>Token/API/人民币成本未知</strong>，不根据一般价格印象估算。「开源」不等于「模型免费」——成本由 Portal、API、托管和本地硬件共同决定。</p><h2 id="_5-核心能力" tabindex="-1">5. 核心能力 <a class="header-anchor" href="#_5-核心能力" aria-label="Permalink to &quot;5. 核心能力&quot;">​</a></h2><ul><li>能处理哪些材料：文档、代码、项目文件；统一基准任务中一次生成 6 份 Markdown；</li><li>能调用哪些工具：文件系统、消息平台、技能与工具、项目文件树、终端、多视图预览（本轮用到文件写入与恢复）；自动化与长期项目能力入口可见；</li><li>代表性功能：四视图切换（预览/源码/差异/编辑）、自动恢复、Provider 多供应商接入、Profiles；</li><li>哪些能力实际验证过：共同基准任务完整链路 + 一次自动恢复；哪些只来自官方说明：消息平台集成、自动化深度能力。</li></ul><h2 id="_6-界面与工作方式" tabindex="-1">6. 界面与工作方式 <a class="header-anchor" href="#_6-界面与工作方式" aria-label="Permalink to &quot;6. 界面与工作方式&quot;">​</a></h2><ul><li>运行位置：本地桌面应用（模型经外部 Provider）；</li><li>用户如何观察和控制执行过程：中间对话流看任务说明与结论，右侧文件树看产物，差异页可看预览/源码/差异/编辑四种形态。</li></ul><table tabindex="0"><thead><tr><th>维度</th><th>观察记录</th><th>适用前提</th></tr></thead><tbody><tr><td>新手上手难度</td><td>较高：Provider/模型/推理/审批/环境概念多</td><td>有配置经验者</td></tr><tr><td>账号与地区可用性</td><td>无产品账号；Provider 可用性即门槛</td><td>供应商状态</td></tr><tr><td>图形界面清晰度</td><td>成熟三栏工作台，GUI 本身易用</td><td>—</td></tr><tr><td>任务状态反馈</td><td>对话流 + 文件树 + 分支上下文</td><td>—</td></tr><tr><td>权限提示与确认</td><td>智能审批 0 弹窗；但未阻止写入禁止目录</td><td>无弹窗 ≠ 无风险</td></tr><tr><td>上下文处理</td><td><strong>越权读取</strong>：可读取整个 Project（自检引用根目录运行文件）</td><td>需以产物与运行记录核对</td></tr><tr><td>过程可控性</td><td>高：多视图核对 + 自动恢复</td><td>—</td></tr><tr><td>结果定位与验证</td><td>四视图（预览/源码/差异/编辑）最灵活</td><td>—</td></tr><tr><td>生态与扩展</td><td>消息平台、技能与工具、Profiles 入口</td><td>未逐一实测</td></tr></tbody></table><p>界面细节见 「界面讲解文档」(docs/11-interface-guides/07-hermes.md)（三张截图：整体界面、预览、差异四视图）。</p><h2 id="_7-三类实测任务" tabindex="-1">7. 三类实测任务 <a class="header-anchor" href="#_7-三类实测任务" aria-label="Permalink to &quot;7. 三类实测任务&quot;">​</a></h2><h3 id="_7-1-共同基准任务-2026-08-12" tabindex="-1">7.1 共同基准任务（2026-08-12） <a class="header-anchor" href="#_7-1-共同基准任务-2026-08-12" aria-label="Permalink to &quot;7.1 共同基准任务（2026-08-12）&quot;">​</a></h3><h4 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h4><p>使用冻结的教程材料包（<code>input/</code> 7 份文件），整理 AI Agent 教程材料，生成六个指定交付文件并自检。</p><h4 id="完整输入" tabindex="-1">完整输入 <a class="header-anchor" href="#完整输入" aria-label="Permalink to &quot;完整输入&quot;">​</a></h4><p>冻结材料包 + <code>hermes-prompt.md</code> 统一提示。</p><h4 id="执行过程" tabindex="-1">执行过程 <a class="header-anchor" href="#执行过程" aria-label="Permalink to &quot;执行过程&quot;">​</a></h4><p>打开 Hermes Desktop → 新建独立 Project 并选择运行目录 → 使用当前已配置 Provider 与模型（不显示/修改密钥）→ 保持默认推理、权限与工具设置 → 粘贴统一提示发送。</p><h4 id="最终结果" tabindex="-1">最终结果 <a class="header-anchor" href="#最终结果" aria-label="Permalink to &quot;最终结果&quot;">​</a></h4><p>约 5–7 分钟完成（测试者记录；首批产物到最后产物写入间隔 1 分 25 秒）。过程中发生一次<strong>自动恢复</strong>：因当前目录位于 <code>input</code>，前两份文件被相对路径误写入 <code>input/output/</code>，随后 Agent 自行迁移到根 <code>output/</code>、删除误建目录并复核输入哈希。</p><h4 id="验收情况" tabindex="-1">验收情况 <a class="header-anchor" href="#验收情况" aria-label="Permalink to &quot;验收情况&quot;">​</a></h4><ul><li>交付：6/6 最终完成，内容详细；7/7 输入 SHA-256 与基线一致；误建目录已清理；</li><li>内容亮点：自检诚实披露路径偏差与修复过程（透明度较高）；信息缺口 A-E 分类完整；</li><li>内容偏差：自行压缩为第 0–7 章目录，只能作为基准答卷不能替换正式 23 章框架；把「误写后清理」仍评为权限边界全部遵守，结论过宽；读取了 input 之外的项目文件；</li><li>指标：澄清 0 / 权限确认 0 / 人工回复 0 / 依赖安装 0 / 中断 0 / 报错 0 / 人工重试 0 / <strong>内部路径偏差 1 / 自动恢复 1</strong>。</li></ul><table tabindex="0"><thead><tr><th>指标</th><th>记录</th></tr></thead><tbody><tr><td>开始与完成时间</td><td>2026-08-12 09:19:57（首批文件）— 09:21:22（最后文件）</td></tr><tr><td>总用时</td><td>约 5–7 分钟</td></tr><tr><td>人工介入次数及原因</td><td>0（自动恢复不计作人工）</td></tr><tr><td>权限确认次数</td><td>0（智能审批未触发）</td></tr><tr><td>生成或修改的交付文件</td><td>6/6 指定文件（含一次误写迁移）</td></tr><tr><td>是否一次通过验收</td><td>指定文件最终一次交付齐全；内容通过，写入/读取边界不完全通过</td></tr><tr><td>失败后的恢复路径</td><td>自动迁移 + 删除误建目录 + SHA-256 复核，无需人工</td></tr></tbody></table><h3 id="_7-2-优势任务" tabindex="-1">7.2 优势任务 <a class="header-anchor" href="#_7-2-优势任务" aria-label="Permalink to &quot;7.2 优势任务&quot;">​</a></h3><p>候选：高自主任务、自定义模型、自动化与长期项目（产品定位方向）。<strong>待 benchmark v2 统一测试</strong>。</p><h3 id="_7-3-边界任务" tabindex="-1">7.3 边界任务 <a class="header-anchor" href="#_7-3-边界任务" aria-label="Permalink to &quot;7.3 边界任务&quot;">​</a></h3><p><strong>本轮已实际触发一次边界场景</strong>（路径误写 + 自动恢复），是七款中唯一的真实恢复案例；更广泛的边界（Provider 不可用、上下文过长、权限拒绝）待 benchmark v2 补测。</p><h2 id="_8-遇到的问题与恢复" tabindex="-1">8. 遇到的问题与恢复 <a class="header-anchor" href="#_8-遇到的问题与恢复" aria-label="Permalink to &quot;8. 遇到的问题与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>出现条件</th><th>对结果的影响</th><th>恢复步骤</th><th>新手能否独立处理</th></tr></thead><tbody><tr><td>相对路径误写到输入目录</td><td>执行时当前目录位于 input，使用相对 output/...</td><td>临时在输入树内创建 input/output/ 并写入两份产物，违反写入边界</td><td>自动迁移到根 output/、删除误建目录、复核 7/7 哈希</td><td>用户侧无提示；若未自检可能难以发现</td></tr><tr><td>读取范围越过 input</td><td>Agent 可读取整个 Project</td><td>自检引用根目录运行文件</td><td>验收标注范围偏差，不采信自检「全部遵守」</td><td>智能审批未弹窗不代表严格限制读取</td></tr><tr><td>成本不可见</td><td>使用外部 Provider/API</td><td>无法换算本轮成本</td><td>记录未知，不估算</td><td>新手需自行理解供应商计费与余额</td></tr></tbody></table><p><strong>教学价值</strong>：Hermes 的误写恢复案例是教程「Harness/权限/恢复」章节的绝佳素材——它清楚演示了「最终正确 ≠ 过程合规」，安全、恢复、透明度应分开评价。</p><h2 id="_9-适合与不适合" tabindex="-1">9. 适合与不适合 <a class="header-anchor" href="#_9-适合与不适合" aria-label="Permalink to &quot;9. 适合与不适合&quot;">​</a></h2><h3 id="更适合" tabindex="-1">更适合 <a class="header-anchor" href="#更适合" aria-label="Permalink to &quot;更适合&quot;">​</a></h3><ul><li>重视模型自由、多供应商接入的自托管用户；</li><li>需要高自主、长期自动化任务的用户；</li><li>愿意承担环境配置与维护责任的读者（四视图核对体验好，配置门槛可接受）。</li></ul><h3 id="可能不适合" tabindex="-1">可能不适合 <a class="header-anchor" href="#可能不适合" aria-label="Permalink to &quot;可能不适合&quot;">​</a></h3><ul><li>零基础新手（Provider/模型/环境概念门槛高）；</li><li>不想管理 API Key 与外部账单的用户（成本不可见）；</li><li>对数据边界有严格要求且不希望「无弹窗越权读取」的用户（本轮存在边界失分）。</li></ul><h2 id="_10-最终结论" tabindex="-1">10. 最终结论 <a class="header-anchor" href="#_10-最终结论" aria-label="Permalink to &quot;10. 最终结论&quot;">​</a></h2><ul><li>是否推荐新手试用：<strong>不优先推荐</strong>——先通过教程第 2 章理解模型/API 概念，再在熟悉环境后试用；</li><li>什么条件下值得购买官方订阅：按需购买 Portal 月度 Credits 或使用自有 API；应用本身开源免费；</li><li>最适合作为主 Agent、辅助 Agent 还是专用工具：<strong>自托管型主 Agent 候选</strong>；高自主任务与自动化场景价值最大；</li><li>与相邻产品的差异：与 ZCode 同属 BYOK 路径，Hermes 恢复能力唯一实证（自动恢复），ZCode 变更统计更细；与托管路径（Codex/WorkBuddy 等）相比，Hermes 配置自由度最高、但开箱即用性最低；</li><li>仍需要后续版本继续核验：Provider 不可用时的恢复、消息平台集成、长期自动化稳定性、精确成本核算。</li></ul><h2 id="附录-a-截图清单" tabindex="-1">附录 A：截图清单 <a class="header-anchor" href="#附录-a-截图清单" aria-label="Permalink to &quot;附录 A：截图清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>截图</th><th>用途</th><th>日期或版本</th><th>是否脱敏</th><th>替代文字</th></tr></thead><tbody><tr><td>整体界面.png</td><td>三栏工作台与会话</td><td>0.17.0</td><td>是（Provider 页面需遮挡密钥）</td><td>三栏项目工作台</td></tr><tr><td>预览详情.png</td><td>Markdown 成品渲染</td><td>同上</td><td>是</td><td>预览页</td></tr><tr><td>差异详情.png</td><td>预览/源码/差异/编辑四视图</td><td>同上</td><td>是</td><td>差异四视图</td></tr></tbody></table><h2 id="附录-b-信息来源" tabindex="-1">附录 B：信息来源 <a class="header-anchor" href="#附录-b-信息来源" aria-label="Permalink to &quot;附录 B：信息来源&quot;">​</a></h2><ul><li><a href="https://hermes-agent.nousresearch.com/" target="_blank" rel="noreferrer">Hermes Agent</a>、<a href="https://github.com/NousResearch/hermes-agent" target="_blank" rel="noreferrer">NousResearch/hermes-agent</a>（访问日期 2026-08-11）</li><li>运行记录：<code>research/runs/2026-08-12-hermes-desktop-v0.17.0/run-record.md</code></li><li>界面讲解：<code>docs/11-interface-guides/07-hermes.md</code></li></ul><h2 id="附录-c-内容性质标记" tabindex="-1">附录 C：内容性质标记 <a class="header-anchor" href="#附录-c-内容性质标记" aria-label="Permalink to &quot;附录 C：内容性质标记&quot;">​</a></h2><p>本文区分：官方事实（开源 License、供应商支持）、实际测试（共同基准任务 + 自动恢复案例）、作者观察（界面与门槛）、待验证（长期自动化、成本核算）。约 5–7 分钟是 Hermes + OpenCode Go + DeepSeek V4 Flash + 最高推理 + 智能审批共同作用的结果；「DeepSeek API 通常较便宜」不是本轮成本证据，成本记录为未知。</p>',50)])])}const p=e(l,[["render",i]]);export{b as __pageData,p as default};
